def check_schema(value: Any, arm: str) -> tuple[bool, list[str]]:
    if not isinstance(value, dict) or set(value) != {"facts"} or not isinstance(value.get("facts"), list):
        return False, ["top_level_facts_schema"]
    required = set(ARMS[arm]["required"])
    errors = []
    for index, item in enumerate(value["facts"]):
        if not isinstance(item, dict) or set(item) != required:
            errors.append(f"fact_{index}_keys")
            continue
        if not isinstance(item.get("fact"), str) or not item["fact"]:
            errors.append(f"fact_{index}_fact")
        if item.get("status") not in ALLOWED_STATUS:
            errors.append(f"fact_{index}_status")
        if item.get("speaker") is not None and not isinstance(item.get("speaker"), str):
            errors.append(f"fact_{index}_speaker")
        if arm == "a_full" and (not isinstance(item.get("evidence"), str) or not item["evidence"]):
            errors.append(f"fact_{index}_evidence")
        if arm == "c2_full" and (not isinstance(item.get("evidence_ids"), list) or not all(isinstance(x, str) for x in item["evidence_ids"])):
            errors.append(f"fact_{index}_evidence_ids")
        if arm == "d_range" and (not isinstance(item.get("evidence_ranges"), list) or not all(isinstance(x, str) for x in item["evidence_ranges"])):
            errors.append(f"fact_{index}_evidence_ranges")
        if arm == "e_unit_quote":
            if not isinstance(item.get("unit_ids"), list) or not all(isinstance(x, str) for x in item["unit_ids"]):
                errors.append(f"fact_{index}_unit_ids")
            if not isinstance(item.get("quote"), str) or not item["quote"]:
                errors.append(f"fact_{index}_quote")
    return not errors, errors
